      mechanism: { eyebrow:"Anatomia techniczna", title:"Dwie ścieżki. Jedno przerwane kontrakt.", intro:"Ten defensywny model pokazuje przejścia stanu — bez kodu exploita. Wyjaśnia, dlaczego parsowanie żądań, czyszczenie, ponowne użycie procesu i uwierzytelnianie aplikacji leżą po przeciwnych stronach granicy awarii.", cve1:"CVE-2026-109618 · Korupcja OOM", cve1s:"Stan należący do żądania staje się osiągalny przed zakończeniem inicjalizacji. Kontrolowane OOM pozostawia nieprawidłowe dane, które czyszczenie może odczytać lub na których oprze decyzję.", cve2:"CVE-2026-109619 · Przestarzały stan globalny", cve2s:"Stan żądania zostaje opublikowany w globalnych strukturach procesu. Sterta żądania jest zwalniana, ale wskaźnik przetrwa i zostanie wykorzystany przez kolejne żądanie.", contract:"Przerwany kontrakt", contractText:"Stan opublikowany → zawodna alokacja lub ścieżka krytyczna → wczesne wyjście → czyszczenie lub kolejne żądanie ufa nieaktualnemu stanowi → wyciek pamięci / RCE", app:"Kod aplikacji", appNote:"Może nigdy nie wystąpić", parser:"Parser HTTP", parserNote:"Multipart / upload", heap:"Sterta żądania", heapNote:"Częściowo zainicjalizowana", bailout:"OOM / błąd krytyczny", bailoutNote:"longjmp / gwałtowne wyjście", cleanup:"Czyszczenie po żądaniu", cleanupNote:"Czyta nieprawidłowy stan", worker:"Ten sam proces", workerNote:"Późniejsze żądanie", auth:"Uwierzytelnianie", authNote:"Nieosiągnięte", boundary:"GRANICA ŻĄDANIA / PROCESU", legend:"Aplikacja może poprawnie uwierzytelniać — i to nie ma znaczenia. Luka działa w runtime, zanim wykona się kod użytkownika." },
      sapi: { eyebrow:"Różnice środowisk", title:"SAPI zmienia promień rażenia", intro:"Wszystkie SAPI obsługujące ruch web są objęte analizą. Oficjalne advisory publikują poprawki dla utrzymywanych gałęzi 8.2–8.5; badacze niezależnie oceniają starsze ścieżki sięgające PHP 5.4. Najprostsza ścieżka sprzed aplikacji jest najsilniejsza w Apache mod_php, gdzie czyszczenie działa nawet po nieudanym starcie żądania.", mod:"Apache mod_php", mods:"Najwyższe ryzyko", modd:"Nieudany start nadal wywołuje czyszczenie żądania; nieprawidłowy stan zostaje skonsumowany w tym samym żądaniu.", fpm:"PHP-FPM", fpms:"Ścieżka warunkowa", fpmd:"Nieudany start kończy proces potomny. Pozostają ścieżki zależne od aplikacji oraz cyklu stanu między żądaniami.", others:"php-cgi · FrankenPHP · LiteSpeed", othersd:"Ekspozycja zależy od zachowania startu, shutdownu i ponownego użycia procesu. Każde wdrożenie SAPI należy zweryfikować osobno." },
      exposure: { eyebrow:"Globalna powierzchnia", title:"Długi ogon jest właściwą powierzchnią ataku", intro:"Skanery internetowe liczą różne rzeczy. Odporny wniosek nie brzmi „jedna liczba”: widocznych jest miliony usług PHP, a znaczna część działa na już niewspieranych gałęziach.", modat:"Skan Modat", modatv:"4,38 mln usług PHP", modatd:"1,89 mln unikalnych hostów · 79% na niewspieranych gałęziach według migawki skanu z ok. 20 października.", vul:"Skan VulnCheck", vulv:"2,61 mln hostów", vuld:"Ponad 1,1 mln na gałęziach EOL; tylko 403 tys. na utrzymywanych gałęziach 8.2–8.5 według raportowanego skanu.", censys:"Skan Censys", censysv:"56,6 mln właściwości webowych", censysd:"3,08 mln hostów wykrytych z PHP; inny migawkowy pomiar innej jednostki ekspozycji.", verdict:"Wniosek operacyjny", verdictd:"Natychmiast załataj wspierane gałęzie. Odłącz lub wycofaj środowiska EOL. Zinwentaryzuj osadzone PHP i aplikacje sprzętowe. Sprawdzaj runtime obsługujący ruch — nie tylko binarny CLI.", eol:"Presja cyklu życia", eold:"PHP 8.2 osiąga EOL 31 grudnia 2026 r. Poprawka bezpieczeństwa jest mostem, nie decyzją architektoniczną." },
      potassium: { eyebrow:"Aktywność zagrożeń", title:"Potassium: próbowany łańcuch dostarczania", intro:"Rodzinę wywodzącą się z Mirai powiązano ze skanowaniem PHP2Shell i próbami dostarczenia loadera. Badacze udokumentowali łańcuch; masowe udane przejęcia PHP2Shell nie były publicznie potwierdzone we wczesnych raportach.", chain:"Łańcuch ataku", loader:"Serwer loadera ELF", c2:"Kanał C2", flood:"Cele DDoS", warn:"Dyscyplina dowodowa", warnd:"Poniższe wskaźniki to defensywne IOC z badań. Nie testuj ich z produkcyjnych sieci. Używaj ich jako kandydatów do blokady wyłącznie w zatwierdzonym procesie zmian." },
      response: { eyebrow:"Playbook reagowania", title:"Zabezpiecz dowody. Załataj. Cofnij się w czasie.", intro:"Czteroetapowa sekwencja zsyntezowana z oficjalnych wytycznych PHP i krajowych alertów CERT. W razie konfliktów źródeł rozstrzyga oficjalne ostrzeżenie producenta.", s1:"01 · Zabezpiecz dowody", s1d:"Odizoluj host lub umieść go za restrykcyjnym WAF. Wykonaj migawki VM/kontenera i zrzut żywej RAM przed restartem procesów PHP — restart niszczy dowody z manipulacji stertą i wycieku pamięci.", s2:"02 · Zaktualizuj i zrestartuj", s2d:"Przenieś wspierane gałęzie na PHP 8.5.12, 8.4.27, 8.3.36 lub 8.2.35. Przebuduj obrazy i zrestartuj każdy proces PHP. EOL wymaga zweryfikowanych backportów lub izolacji sieciowej.", s3:"03 · Zastosuj środki tymczasowe", s3d:"Wyłącz postęp przesyłania sesji i ślady stosu błędów w PHP 8.5, jeśli właściwe. Wymusz limity dekodowanego żądania na brzegu. Nigdy nie zastępuj limitów PHP przez RLIMIT_AS lub RLIMIT_DATA.", s4:"04 · Huntuj i rotuj", s4d:"Przeszukaj logi od 17 października. Skoreluj błędy limitu pamięci, nietypowe multiparty, duże PHPSESSID i procesy WWW uruchamiające powłoki. Po oknie ekspozycji rotuj sekrety.", matrix:"Macierz poprawek", directive:"Dyrektywa / kontrola", value:"Wartość", why:"Cel", caveat:"Ograniczenie", c1:"session.upload_progress.enabled", v1:"0 / Off", w1:"Blokuje ścieżki postępu sesji", x1:"Środek tymczasowy; restart procesów", c2:"fatal_error_backtraces", v2:"0", w2:"Usuwa potwierdzony producent w PHP 8.5", x2:"Nie pokrywa każdej ścieżki stanu globalnego", c3:"memory_limit", v3:"-1 (wymuszone przez admina)", w3:"Unika przewidywalnego progu OOM PHP", x3:"Nie jest pełne; zastosuj izolację cgroup/kontenera", c4:"post_max_size + limity brzegowe", v4:"Konserwatywne", w4:"Ogranicza inflację żądania / multipart", x4:"Mityguje strategię OOM; poprawka jest obowiązkowa", c5:"RLIMIT_AS / RLIMIT_DATA", v5:"Nie używaj", w5:"Unika wywołania tego samego błędu alokacji", x5:"Nie jest kontrolą bezpieczeństwa PHP" },
      findings: { eyebrow:"Wnioski strategiczne", title:"Cztery lekcje wykraczające poza łatkę", f1:"AI kompresuje ekonomię exploita", f1d:"Defensywna AI skróciła drogę od trudnej podatności pamięci do powtarzalnego exploita. Ta sama możliwość obniża koszt po stronie atakujących.", f2:"Embargo nie jest granicą zaufania", f2d:"Sieć ujawniania obejmowała dystrybutorów, badaczy, dostawców i obrońców. Założeniem operacyjnym musi być exploit przed publikacją biuletynu.", f3:"Brak logów nie oznacza braku naruszenia", f3d:"Żądanie może zawieźć przed uruchomieniem logowania aplikacji. Po załataniu runtime nadal oceń sekrety w pamięci i je rotuj.", f4:"Utrzymanie open source jest ryzykiem systemowym", f4d:"Krytyczna infrastruktura zależy od małej społeczności utrzymującej. Finansowanie, pojemność recenzji i mechanika decyzji są częścią powierzchni ataku." },
